using namespace std;


// Function to check if a number is prime
bool isPrime(int n) {
    // 0 and 1 are not prime numbers
    if (n <= 1) return false;

    // Check divisibility from 2 up to the square root of n
    for (int i = 2; i * i <= n; ++i) {
        if (n % i == 0) return false;
    }

    return true;
}


int main() {
    int num;
    cout << "Enter an integer: ";
    cin >> num;

    vector<int> factors;

    // Find all factors of the input number
    for (int i = 1; i <= num / 2; ++i) {
        if (num % i == 0) {
            factors.push_back(i);
        }
    }
    factors.push_back(num); // Include the number itself as a factor

    // Display factors that are prime numbers
    cout << "Factors which are primes:" << endl;
    for (int factor : factors) {
        if (isPrime(factor)) {
            cout << factor << " ";
        }
    }
    cout << endl;

    return 0;
}

