from collections import deque 
def is_valid_path(board, path):
    queue = deque([(path[0], [path[0]])]) 

    while queue:
        (current_cell, current_path) = queue.popleft()

        if len(current_path) == len(path):
            return True

        for direction in ['up', 'down', 'left', 'right']:
            new_row = current_cell[0] + {'up': -1, 'down': 1}[direction]
            new_col = current_cell[1] + {'left': -1, 'right': 1}[direction]

            if 0 <= new_row < len(board) and 0 <= new_col < len(board[0]):
                new_cell = (new_row, new_col)

                if new_cell not in board or (new_cell not in current_path and new_cell != board[new_row][new_col]):
                    new_path = current_path + [new_cell]

                    if new_cell in path:
                        continue

                    queue.append((new_cell, new_path))

    return False

