class Solution {
  static String solve(List<String> lines) {
    int n = lines.length;

    Map<int, List<int>> grid = {};

    for (int i = 0; i < n; ++i) {
      String line = lines[i];
      int m = line.length - 1;

      if (!grid.containsKey(i)) {
        grid.addEntry(i, []);
      }

      grid[i].add(m);
    }

    int maxRowsAffectedByOneMove = 0;

    for (List<int> rowIndices in grid.values) {
      // Get the columns that are affected by a move on this row.
      Set<int> colsAffectedByRow = {};
      for (int colIndex : rowIndices) {
        colsAffectedByRow.add(colIndex);

        // If there's already another row with an adjacent column index...
        if (colsAffectedByRow.contains(colIndex + 1) || 
            colsAffectedByRow.contains(colIndex - 1)) {
          return 'NO';
        }
      }

      if (rowIndices.length == 1) continue;

      // Otherwise we need to check if it is possible to move every other piece in this row so no two pieces have adjacent columns.
      boolean canMovePiecesInThisRowWithoutConflict = true;
      for (int j = 0; j < rowIndices.length; ++j) {
        int colIndexToMovePieceFrom = rowIndices[j];

        // Check whether all columns from `colIndexToMovePieceFrom` and above were free of conflicts before moving any of these pieces.
        for (int k = j + 1; k < rowIndices.length && colIndexToMovePieceFrom >= 0; --k) {
          int nextColIndexToMovePieceFrom = rowIndices[k];

          if ((nextColIndexToMovePieceFrom > colIndexToMovePieceFrom) && !canMovePiecesInThisRowWithoutConflict) break;

          if (Math.abs(nextColIndexToMovePieceFrom - colIndexToMovePieceFrom) <= 1) {
            canMovePiecesInThisRowWithoutConflict = false;
            break;
          }
        }

        if (colIndexToMovePieceFrom != 0) {
          for (int l = 0; l < j; ++l) {
            int prevColIndexToMovePieceFrom = rowIndices[l];

            if (prevColIndexToMovePieceFrom == colIndexToMovePieceFrom - 2) {
              canMovePiecesInThisRowWithoutConflict = false;
              break;
            } else if (prevColIndexToMovePieceFrom == colIndexToMovePieceFrom - 3 && Math.abs(prevColIndexToMovePieceFrom - rowIndices[(l + 1) % rowIndices.length]) <= 1) {
              canMovePiecesInThisRowWithoutConflict = false;
              break;
            }
          }
        }

        if (!canMovePiecesInThisRowWithoutConflict) break;
      }

      if (!canMovePiecesInThisRowWithoutConflict) return 'NO';

      maxRowsAffectedByOneMove++;
    }

    return maxRowsAffectedByOneMove == n ? 'YES' : 'NO';
  }
}

