String calculate(int n, int m) {
  var count = 0;

  for (var i = 0; i < n; ++i) {
    for (var j = 0; j < m; ++j) {
      for (var k = 0; k < m - 1; ++k) {
        for (var l = 0; l < m - 1; ++l) {
          if ((i + j) % 3 == (k + l) % 3 && 
              (i * j) % 4 == (k * l) % 4) {
            ++count;
          }
        }
      }
    }
  }

  return count.toString();
}

