/// Función que calcula los primeros 10 números de Fibonacci.
List<int> fibonacci() {
  /// Inicializa una lista con los dos primeros números de Fibonacci: 0 y 1.
  List<int> result = [0, 1];

  /// Itera desde el tercer número hasta el décimo (índice 9) para calcular cada número siguiente.
  for (int i = 2; i < 10; i++) {
    /// El siguiente número es la suma de los dos anteriores.
    int nextFibonacci = result[i - 1] + result[i - 2];

    /// Añade este nuevo número a la lista resultante.
    result.add(nextFibonacci);
  }

  /// Devuelve la lista completa de los primeros 10 números de Fibonacci.
  return result;
}

void main(List<String> arguments) {
  /// Llama a la función fibonacci y almacena su resultado en una variable llamada 'fib'.
  var fib = fibonacci();

  /// Imprime todos los elementos de la lista 'fib' al console.
  print(fib.join(''));
}

