bool prepareConvexHulls(List<Point> points) {
  // Implementation of the Graham's scan algorithm to find convex hulls.

  if (points.length < 3) return false;

  Point p0 = points[0];
  int minIndex = 1;
  for (int i = 2; i < points.length; i++) {
    double angleToP0 = Math.atan(points[i].y - p0.y);
    double angleToMin = Math.atan(points[minIndex].y - p0.y);
    if (angleToP0 > angleToMin || (angleToP0 == angleToMin &&
        Math.sqrt((points[i].x - p0.x).pow(2) + (points[i].y - p0.y).pow(2)) >
            Math.sqrt((points[minIndex].x - p0.x).pow(2) +
                    (points[minIndex].y - p0.y).pow(2)))) {
      minIndex = i;
    }
  }

  List<Point> sortedPoints = [p0, ...points.sublist(minIndex)];
  sortedPoints.addAll([...points.sublist(0, minIndex)]);

  Stack<Point> stack = [];
  stack.push(sortedPoints.first);
  stack.push(sortedPoints.last);

  for (Point point in sortedPoints.skip(1).skipLast()) {
    while (stack.length >= 2 &&
        isRightTurn(stack.elementAt(-1), stack.elementAt(-2), point)) {
      stack.pop();
    }
    stack.push(point);
  }

  List<Point> convexHull = stack.toList()..removeAt(-1)..removeAt(-1);
  return convexHull.isNotEmpty ? true : false;
}

class ConvexHull {
  static List<Point> prepareConvexHulls(List<Point> points) {
    final hull = <Point>[];
    if (points.length == 0) return hull;

    Point leftmost = null;
    for (var p in points) {
      if (leftmost == null || p.x < leftmost.x) {
        leftmost = p;
      }
    }

    var upper = _grahamScan(leftmost, points);
    var lower = _grahamScan(lower: leftmost, points.reversed.toList());

    // Merge the two halves, removing duplicate endpoints.
    int i = 1, j = 1;
    while (i < upper.length && j < lower.length - 2) {
      if (upper[i].y > lower[j].y) {
        hull.add(upper[i++]);
      } else {
        hull.add(lower[j++]);
      }
    }

    hull.addAll(upper.sublist(i));
    hull.addAll(lower.sublist(j + 1));

    return hull;
  }

  static List<Point> _grahamScan({required Point origin, required Iterable<Point> pts}) {
    if (pts.isEmpty) return [];

    // Sort by polar angle around 'origin'.
    var sorted = [...pts]..sort((a, b) => a.compareToPolar(origin, b));

    Stack<Point> s = [sorted[0], sorted[1]];

    for (int k = 2; k < sorted.length; ++k) {
      while (s.length >= 2 && !isLeftTurn(s[s.length - 2], s.last, sorted[k])) {
        s.removeLast();
      }
      s.add(sorted[k]);
    }

    return s.toList()..removeAt(0); // remove duplicated start point.
  }

  static bool isLeftTurn(Point o, Point a, Point b) {
    double crossProd = (b.x - a.x) * (o.y - a.y) - (b.y - a.y) * (o.x - a.x);
    return crossProd > 0;
  }

}

