int legendreSymbol(int a, int p) {
  if (p == 2 || p == -1) return 0;
  var res = 1;

  for (var i = 0; i < p / 2; ++i) {
    var j = ((a * i + p) % p);

    res *= j;
  }

  res %= p;

  if (res != 0 && res == p - 1) return -1;
  else return 0;
}

