void lineout(List<int> s) {
  List<String> result = [];

  // First pass: collect all distinct elements and their last occurrence indices
  Map<int, int> lastIndexMap = {};

  for (int i = 0; i < s.length; i++) {
    if (!lastIndexMap.containsKey(s[i])) {
      lastIndexMap[s[i]] = i;
    } else {
      lastIndexMap.remove(s[i]);
    }
  }

  // Sort by the last occurrence index in descending order
  List<MapEntry<int, int>> sortedEntries = 
      lastIndexMap.entries.toList()..sort((a, b) => b.value.compareTo(a.value));

  // Output each element followed by a space at its last position only
  for (var entry in sortedEntries) {
    result.add(entry.key.toString());
  }

  print(result.join(' '));
}

